cat > /workspace/project/src/replay_api.c <<'EOF'
/* Offline transport ABI: the collector is driven entirely by replayed frames. */

#include "collector.h"
#include "epic_clean.h"

#include <stdlib.h>
#include <string.h>

void *epic_open(int primitive, int mode, int root, uint32_t count, uint32_t words,
                uint32_t capacity, uint32_t start, epic_emit_fn emit, void *user)
{
    return collector_open(primitive, mode, root, count, words, capacity, start,
                          emit, user);
}

void epic_close(void *context)
{
    collector_close((collector_t *)context);
}

int epic_ingress(void *context, int rank, const uint8_t *frame, size_t length)
{
    return collector_ingress((collector_t *)context, rank, frame, length);
}

int epic_flush(void *context)
{
    return collector_flush((collector_t *)context);
}

int epic_retry(void *context, int rank)
{
    return collector_retry((collector_t *)context, rank);
}

void epic_state(void *context, uint64_t *state)
{
    collector_state((collector_t *)context, state);
}

uint64_t epic_digest(void *context)
{
    return collector_digest((collector_t *)context);
}
EOF
cd /workspace/project && python3 - <<'EOF'
import re,pathlib
p=pathlib.Path('src/roce_packet.c')
s=p.read_text()
old="""    uint8_t buf[8 + sizeof(epic_ipv4_t) + sizeof(epic_udp_t) +
                sizeof(epic_bth_t) + EPIC_MAX_PAYLOAD_BYTES];"""
new="""    uint8_t buf[8 + sizeof(epic_ipv4_t) + sizeof(epic_udp_t) +
                sizeof(epic_bth_t) + EPIC_MAX_PAYLOAD_BYTES + 64];"""
assert old in s
s=s.replace(old,new)
p.write_text(s)
print("patched")
EOF
