CC = gcc
BUILD ?= build
CFLAGS = -std=c11 -O2 -fPIC -Wall -Wextra -Wno-unused-function -Wno-unused-parameter
SOURCES = src/replay_api.c src/roce_packet.c src/star4_switch.c
